import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import MainNav from "../../MainNav/MainNav";

const ArtistLogin = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError(""); // reset error

    try {
      const res = await axios.post("http://localhost:5000/api/registeredArtists/login", {
        email,
        password,
      });

      const artist = res.data.artist;
      // Successful login
      alert(res.data.message);

      // Redirect to portfolio page
      navigate(`/artist_portfolio/${artist.id}`);
    } catch (err) {
      console.error(err);

      if (err.response && err.response.data && err.response.data.message) {
        // Show backend message like "Artist not approved yet"
        setError(err.response.data.message);
      } else {
        setError("Server error. Try again later.");
      }
    }
  };

  return (
    <div>
      <MainNav />
      <div style={{ maxWidth: "400px", margin: "50px auto", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2 style={{ textAlign: "center" }}>Artist Login</h2>
        {error && <p style={{ color: "red", textAlign: "center" }}>{error}</p>}
        <form onSubmit={handleLogin}>
          <div style={{ marginBottom: "15px" }}>
            <label>Email:</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>
          <div style={{ marginBottom: "15px" }}>
            <label>Password:</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>
          <button
            type="submit"
            style={{ width: "100%", padding: "10px", backgroundColor: "#007bff", color: "#fff", border: "none", borderRadius: "5px" }}
          >
            Login
          </button>
        </form>
      </div>
    </div>
  );
};

export default ArtistLogin;
